#!/bin/bash
# Copyright (c) 2026 Eclipse ThreadX contributors
# SPDX-License-Identifier: MIT
# Some portions generated by Claude Code (Opus 5).
#
# Run the ThreadX module manager demonstration on the S32Z280-594EVB and capture
# the evidence: the console log and the fault registers.
#
# Usage:  tools/run_module_demo.sh [<build directory>]
#
# Paths that vary by machine come from the environment: S32DS_ROOT, S32Z280_PROBE
# and GDB_PY_HOME, each described where it is resolved below.  UART and LOG
# override the console device and the capture file.
#
# The console is the test method here, not a convenience, so this captures the
# UART to a file before the image runs and prints the captured bytes afterwards.
# Both LINFlexD bugs found during bring-up were invisible from the target and
# showed up only in a byte diff of a captured log.
#
# Prerequisites this cannot do for you:
#   * the *Windows* CCS listening on 41475, started as "ccs.exe -noportquit".
#     The Linux CCS's pushes to the probe stall after "Sending code ... done".
#   * board wiring for the console: LIN9 -> daughtercard USB-UART, jumper J248
#     at 1-2, micro-USB at J119 on the daughtercard.
set -u

BUILD=${1:-build_mod}
EVB_BIN="$BUILD/ports/cortex_r52/gnu/example_build/s32z280_evb"
HERE=$(cd "$(dirname "$0")" && pwd)

# Where the tools live.  None of these paths are portable, so each is
# overridable and each is checked before it is used -- a wrong one otherwise
# surfaces as a gdb that will not start or an attach that never connects.
#
#   S32DS_ROOT     the S32 Design Studio installation.  Tried in order: the
#                  variable, a system-wide install, the per-user layout.
#   S32Z280_PROBE  the debug probe, as the gdb scripts expect to address it.
#   GDB_PY_HOME    the source-built CPython that gdb-py needs; see PYTHONHOME
#                  below for why the one inside gdb is not enough.
if [ -n "${S32DS_ROOT:-}" ]; then
    R=$S32DS_ROOT
elif [ -d /opt/nxp/S32DS.3.6.10 ]; then
    R=/opt/nxp/S32DS.3.6.10
else
    R=$HOME/NXP/S32DS.3.6.10
fi

if [ ! -d "$R" ]; then
    echo "ERROR: S32 Design Studio not found at $R" >&2
    echo "       Set S32DS_ROOT to your installation, for example:" >&2
    echo "         S32DS_ROOT=/opt/nxp/S32DS.3.6.10 $0 ${1:-}" >&2
    exit 1
fi

GDB=$R/S32DS/tools/gdb-arm/arm32-eabi/bin/arm-none-eabi-gdb-py
GTA=$R/S32DS/tools/S32Debugger/Debugger/Server/gta

for f in "$GDB" "$GTA/gta"; do
    if [ ! -x "$f" ]; then
        echo "ERROR: $f is missing or not executable." >&2
        echo "       S32DS_ROOT=$R does not look like an S32 Design Studio install." >&2
        exit 1
    fi
done

# Resolved here and exported, so the gdb scripts use these values rather than
# resolving the same defaults again and possibly differently.
export S32DS_ROOT=$R
export S32Z280_PROBE=${S32Z280_PROBE:-s32dbg:192.168.50.238}

echo "S32DS_ROOT    = $R"
echo "S32Z280_PROBE = $S32Z280_PROBE"

MANAGER_ELF=$EVB_BIN/s32z280_module.elf
MODULE_ELF=$EVB_BIN/s32z280_demo_module.elf
UART=${UART:-/dev/ttyUSB0}
LOG=${LOG:-/tmp/module_demo_uart.log}

for f in "$MANAGER_ELF" "$MODULE_ELF"; do
    if [ ! -f "$f" ]; then
        echo "ERROR: $f not found. Build it first:" >&2
        echo "  ninja -C $BUILD s32z280_module.elf" >&2
        exit 1
    fi
done

# gdb-py needs the source-built interpreter: its embedded Python has a minimal
# builtin set and loads _struct/_socket/_ctypes as separate .so files.  Compute
# the module address BEFORE exporting PYTHONHOME, since that breaks system tools.
# What is wanted is an OFFSET, not an address.  The module is position
# independent: the address nm reports is a nominal one from a segment the module
# never runs at, and its real data lives wherever the manager allocated it -- a
# different place in each pass.  So the offset of module_progress
# within the module's data segment is computed here, and the gdb script adds it
# to each pass's data base, which it reads off the target.
PROGRESS_SYM=$(nm "$MODULE_ELF" | awk '$3=="module_progress"{print $1}')
DATA_SEG=$(nm "$MODULE_ELF" | awk '$3=="__data_segment_start__"{print $1}')
if [ -z "$PROGRESS_SYM" ] || [ -z "$DATA_SEG" ]; then
    echo "ERROR: module_progress or __data_segment_start__ not found in $MODULE_ELF" >&2
    exit 1
fi
PROGRESS_OFFSET=$(( 0x$PROGRESS_SYM - 0x$DATA_SEG ))
if [ "$PROGRESS_OFFSET" -lt 0 ]; then
    echo "ERROR: module_progress is below the module's data segment; the link map" >&2
    echo "       and this script disagree about where the module's data starts." >&2
    exit 1
fi
echo "module_progress is $PROGRESS_OFFSET bytes into the module's data segment"
echo "  (nominal 0x$PROGRESS_SYM, data segment 0x$DATA_SEG -- neither is a real address)"

if pgrep -x ccs > /dev/null; then
    echo "ERROR: a Linux CCS is running (pid $(pgrep -x ccs | tr '\n' ' '))." >&2
    echo "       It holds 41475 and blocks the Windows CCS. Kill it: pkill -x ccs" >&2
    exit 1
fi
# /dev/tcp rather than a Python probe: PYTHONHOME below points at the
# source-built 3.10 for gdb-py, which would make system python3 fail and this
# check spuriously report "no CCS".
if ! timeout 5 bash -c "exec 3<>/dev/tcp/127.0.0.1/41475" 2>/dev/null; then
    echo "ERROR: nothing listening on 41475." >&2
    echo "       CCS quits when its client disconnects unless started with" >&2
    echo "       -noportquit. Relaunch on Windows as:  ccs.exe -noportquit" >&2
    exit 1
fi

# --- console capture, started BEFORE the image runs -------------------------
if [ -c "$UART" ]; then
    stty -F "$UART" 115200 cs8 -parenb -cstopb -crtscts raw -echo
    : > "$LOG"
    cat "$UART" > "$LOG" &
    CAT_PID=$!
    echo "capturing $UART -> $LOG (pid $CAT_PID)"
else
    CAT_PID=""
    echo "WARNING: $UART is not a character device; running without a console capture." >&2
fi

cleanup() {
    if [ -n "$CAT_PID" ]; then
        kill "$CAT_PID" 2>/dev/null || true
    fi
}
trap cleanup EXIT

P=${GDB_PY_HOME:-$HOME/toolchains/py310-src}
if [ ! -d "$P/lib/python3.10" ]; then
    echo "ERROR: no source-built CPython 3.10 at $P" >&2
    echo "       gdb-py's embedded interpreter loads _struct, _socket and" >&2
    echo "       _ctypes as separate .so files and needs a real install to" >&2
    echo "       find them.  Set GDB_PY_HOME to one." >&2
    exit 1
fi
export PYTHONHOME=$P
export PYTHONPATH=$P/lib/python3.10:$P/lib/python3.10/lib-dynload:$P/lib/python3.10/site-packages
export S32Z280_ELF=$MANAGER_ELF
export S32Z280_MODULE_ELF=$MODULE_ELF
export S32Z280_MODULE_PROGRESS_OFFSET=$PROGRESS_OFFSET

# pkill -x, not -f: these run as ./gta, so a -f pattern like 'gta/gta' never
# matches and a stale server silently serves the next attach.
pkill -x gta 2>/dev/null
sleep 2
( cd "$GTA" && nohup ./gta -p 45000 -k > /tmp/gta_module_demo.log 2>&1 & )
sleep 4
if ! pgrep -x gta > /dev/null; then
    echo "ERROR: GTA failed to start; see /tmp/gta_module_demo.log" >&2
    exit 1
fi

timeout -k 20 500 "$GDB" -batch -x "$HERE/run_module_demo.gdb"
rc=$?

# Let the last of the console output arrive before the capture is torn down.
sleep 2

echo ""
echo "===== console, as captured from $UART ====="
if [ -s "$LOG" ]; then
    cat "$LOG"
else
    echo "(nothing arrived on the console)"
    echo "Check: jumper J248 at 1-2, micro-USB at J119 on the daughtercard, and"
    echo "LED J122 for board-to-host traffic."
fi
echo "===== end of console ====="
echo "=== gdb exit=$rc ==="
exit $rc
